variables.input:
timeseries n = count(zeebe.health), by: {k8s.namespace.name}
| fields k8s.namespace.name
| sort k8s.namespace.name asc

5.query:
timeseries retry_per_sec = sum(zeebe.stream.processor.batch.processing.retry, rate:1s),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

9.query:
timeseries exported_position = max(zeebe.exporter.last.updated.exported.position),
  by: {exporter, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

10.query:
timeseries appended_position = max(zeebe.log.appender.last.appended.position),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

11.query:
timeseries committed_position = max(zeebe.log.appender.last.committed.position),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

12.query:
timeseries processed_position = max(zeebe.stream.processor.last.processed.position),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

13.query:
timeseries source_position = max(zeebe.replay.last.source.position),
  by: {partition, k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

15.query:
timeseries exported_position = max(zeebe.exporter.last.exported.position, filter:{exporter == "elasticsearch"}),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

16.query:
timeseries processor_state = max(zeebe.stream.processor.state),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

17.query:
timeseries exporter_state = max(zeebe.exporter.state),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

18.query:
timeseries banned_instances = max(zeebe.banned.instances.total),
  by: {k8s.namespace.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

19.query:
timeseries messages_count = max(zeebe.buffered.messages.count),
  by: {partition, k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

20.query:
timeseries cache_size = max(zeebe.stream.processor.scheduled.command.cache.size),
  by: {k8s.pod.name, partitionId, intent},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

22.query:
timeseries instance_events_per_sec = sum(zeebe.element.instance.events.total, rate:1s, filter:{type == "PROCESS"}),
  by: {action},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

23.query:
timeseries job_events_per_sec = sum(zeebe.job.events.total, rate:1s),
  by: {action},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

26.query:
timeseries processor_records_per_sec = sum(zeebe.stream.processor.records.total, rate:1s),
  by: {action, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

27.query:
timeseries exporter_events_per_sec = sum(zeebe.exporter.events.total, rate:1s),
  by: {partition, k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

28.query:
timeseries replay_events_per_sec = sum(zeebe.replay.events.total, rate:1s),
  by: {partition, k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

29.query:
timeseries executed_instances_per_sec = sum(zeebe.executed.instances.total, rate:1s, filter:{action == "activated"}),
  by: {k8s.namespace.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

30.query:
timeseries executed_instances_per_sec = sum(zeebe.executed.instances.total, rate:1s, filter:{action == "completed"}),
  by: {k8s.namespace.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

31.query:
timeseries job_events_per_sec = sum(zeebe.job.events.total, rate:1s, filter:{action == "created"}),
  by: {k8s.namespace.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

32.query:
timeseries job_events_per_sec = sum(zeebe.job.events.total, rate:1s, filter:{action == "completed"}),
  by: {k8s.namespace.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

49.query:
timeseries requests_count = sum(zeebe.backpressure.inflight.requests.count),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

50.query:
timeseries request_count_per_sec = sum(zeebe.dropped.request.count.total, rate:1s),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}
